<!-- vml {"v":2,"rows":[{"height":190,"widths":[1.223,0.777],"captions":["Fine-tuning parameters vs. accuracy {#fig:eval}","GPT-2 scale and zero-shot performance {#fig:gpt2}"]}]} -->
